function a(e){const t=o=>{e.setSparkUrme("notepad",[o])};return[{target:"#notepad",title:"Welcome to Alphabet Soup",icon:"fad fa-book-spells",color:"#ffaa00",content:"This is your tasty CMS. It allows you to build custom schemas, posts, and pages right inside YouMeOS.",placement:"right",onEnter:()=>t("intro")},{target:"#notepad #nav-item-_schemas",title:"1. Create Custom Schemas",icon:"fad fa-book-spells",color:"#ffaa00",content:"First, you define your content types. You can create completely custom schemas with your own fields and icons.",placement:"right",onEnter:()=>t("_schemas")},{target:"#notepad #nav-item-post",title:"2. Write Posts",icon:"fad fa-book-spells",color:"#ffaa00",content:"Then, use your schemas to write rich content. The built-in editor supports Markdown and dynamic blocks.",placement:"right",onEnter:()=>t("post")},{target:"#notepad #nav-item-page",title:"3. Build Pages",icon:"fad fa-book-spells",color:"#ffaa00",content:"Finally, structure your content into standalone pages. Alphabet Soup is the backbone of your digital presence.",placement:"right",onEnter:()=>t("page")}]}export{a as getNotepadTourSteps};
